<template><section class="admin-page"><header class="admin-page__heading"><p class="admin-page__eyebrow">提效工具</p><h1>工具管理</h1><RouterLink class="admin-button" :to="{name:'admin-tool-new'}">新建工具</RouterLink></header><label>状态筛选 <select v-model="status" @change="filter"><option value="">全部</option><option value="DRAFT">草稿</option><option value="PUBLISHED">已发布</option><option value="ARCHIVED">已归档</option></select></label><div class="admin-card"><article v-for="(tool,i) in data.items" :key="tool.id" class="row" draggable="true" @dragstart="drag=i" @dragover.prevent @drop="move(i-drag)"><div><h2>{{tool.name}}</h2><p>{{tool.status}} · {{tool.officialUrl}}</p></div><button :disabled="page===0 && i===0" :aria-label="`上移 ${tool.name}`" @click="moveAt(i,-1)">↑</button><button :disabled="page+1>=data.totalPages && i===data.items.length-1" :aria-label="`下移 ${tool.name}`" @click="moveAt(i,1)">↓</button><RouterLink :to="{name:'admin-tool-edit',params:{id:tool.id}}">编辑</RouterLink></article><nav><button :disabled="page===0" @click="go(page-1)">上一页</button><span>{{page+1}} / {{Math.max(1,data.totalPages)}}</span><button :disabled="page+1>=data.totalPages" @click="go(page+1)">下一页</button></nav></div><p v-if="error" role="alert">{{error}}</p></section></template>
<script setup lang="ts">import{onMounted,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import type{AdminToolSummaryResponse,PageResponse,ToolStatus}from'../../../shared/api/contracts';import{listAdminTools,reorderTools}from'../admin-api';const route=useRoute(),router=useRouter(),page=ref(Number(route.query.page)||0),status=ref(String(route.query.status??'')),drag=ref(-1),error=ref(''),data=ref<PageResponse<AdminToolSummaryResponse>>({items:[],page:0,size:20,total:0,totalPages:0});async function load(){try{data.value=await listAdminTools({page:page.value,size:20,status:status.value as ToolStatus||undefined})}catch{error.value='工具列表加载失败'}}function filter(){void router.push({query:{page:0,status:status.value||undefined}})}function go(p:number){void router.push({query:{...route.query,page:p}})}async function moveAt(i:number,d:number){const first=await listAdminTools({page:0,size:50});let all=[...first.items];for(let p=1;p<first.totalPages;p++)all.push(...(await listAdminTools({page:p,size:50})).items);const global=all.findIndex(t=>t.id===data.value.items[i]?.id),target=global+d;if(global<0||target<0||target>=all.length)return;[all[global],all[target]]=[all[target]!,all[global]!];try{await reorderTools(all.map(t=>t.id));await load()}catch{error.value="排序保存失败"}}function move(d:number){if(d)void moveAt(drag.value,d)}watch(()=>route.query,()=>{page.value=Number(route.query.page)||0;status.value=String(route.query.status??'');void load()},{deep:true});onMounted(load);</script><style scoped>.row{display:flex;align-items:center;gap:12px;border-bottom:1px solid #e3dbd3}.row div{flex:1}.row h2{font-size:18px}nav{display:flex;justify-content:center;gap:16px;margin-top:20px}</style>
